  suspect_lot_count numeric,
  affected_by_suspect_lot boolean,
  planned_cost numeric,
  actual_cost numeric,
  variance_amount numeric,
  variance_pct numeric,
  readiness_state text,
  source_tables text,
  synthetic boolean,
  source_system text,
  source_table text,
  source_pk text,
  ingest_batch_id text,
  as_of timestamptz,
  serving_provenance text
);
ALTER TABLE rel_build_overview ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY rel_build_overview_tenant ON rel_build_overview
    USING (env_id = current_setting('app.env_id', true))
    WITH CHECK (env_id = current_setting('app.env_id', true));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON TABLE rel_build_overview IS 'SYNTHETIC gold serving mart (Relativity MES Sandbox), Postgres/Lakebase read layer.';
