  closed_ts text,
  age_days numeric,
  disposition_type text,
  affected_vehicle_count numeric,
  estimated_rework_minutes numeric,
  estimated_rework_cost numeric,
  cluster_label text,
  synthetic boolean,
  source_system text,
  source_table text,
