  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='telemetry_app') THEN
    FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'rel\_%' LOOP
      EXECUTE format('GRANT SELECT ON public.%I TO telemetry_app', r.tablename);
    END LOOP;
  END IF;
END $$;
